cases.bad:
// Render body — runs during render, before commit, twice under StrictMode
if (isOpen && searchRef.current) {
  searchRef.current.focus();
}

cases.good:
// useEffect — runs after commit, once, with cleanup path
useEffect(() => {
  if (isOpen) {
    searchRef.current?.focus();
  }
}, [isOpen]);

const [height, setHeight] = useState(0);
useEffect(() => {
  if (ref.current) setHeight(ref.current.offsetHeight);
}, [deps]);
return <div style={{ height }}>...;
